package main

import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/spf13/cobra"
	"go.flipt.io/flipt/internal/cue"
)

type validateCommand struct {
	issueExitCode int
	format        string
}

const (
	jsonFormat = "json"
	textFormat = "text"
)

func newValidateCommand() *cobra.Command {
	v := &validateCommand{}

	cmd := &cobra.Command{
		Use:   "validate",
		Short: "Validate flipt flag state (.yaml, .yml) files",
		Run:   v.run,
	}

	cmd.Flags().IntVar(&v.issueExitCode, "issue-exit-code", 1, "Exit code to use when issues are found")

	cmd.Flags().StringVarP(
		&v.format,
		"format", "F",
		"text",
		"output format: json, text",
	)

	return cmd
}

func (v *validateCommand) run(cmd *cobra.Command, args []string) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	for _, arg := range args {
		f, err := os.ReadFile(arg)
		if err != nil {
			fmt.Println(err)
			os.Exit(1)
		}

		if err := validator.Validate(arg, f); err != nil {
			issues, ok := cue.Unwrap(err)
			if !ok {
				fmt.Println(err)
				os.Exit(1)
			}

			res := cue.Result{Errors: make([]cue.Error, 0, len(issues))}
			for _, issue := range issues {
				switch e := issue.(type) {
				case cue.Error:
					res.Errors = append(res.Errors, e)
				case *cue.Error:
					res.Errors = append(res.Errors, *e)
				default:
					fmt.Println(issue)
					os.Exit(1)
				}
			}

			if v.format == jsonFormat {
				if err := json.NewEncoder(os.Stdout).Encode(res); err != nil {
					fmt.Println(err)
					os.Exit(1)
				}
				os.Exit(v.issueExitCode)
				return
			}

			fmt.Println("Validation failed!")

			for _, e := range res.Errors {
				fmt.Printf(
					`
- Message  : %s
  File     : %s
  Line     : %d
  Column   : %d
`, e.Message, e.Location.File, e.Location.Line, e.Location.Column)
			}

			os.Exit(v.issueExitCode)
		}
	}
}

